import { RichTextEditor } from 'assui';
import type { EditorOptions } from 'tinymce/tinymce';
const firstToolbar =
  'undo redo | blocks fontsize | ' +
  'bold italic underline strikethrough forecolor backcolor charmap emoticons | ' +
  'alignleft aligncenter alignright alignjustify | bullist numlist outdent indent';

const defaultToolbar = [firstToolbar, 'link code table image removeformat | preview help'];

export default function App() {
  const onChange = (value) => {
    console.log('value', value);
  };

  const imagesUploadHandler: EditorOptions['images_upload_handler'] = (blobInfo, progress) => {
    return new Promise((resolve, reject) => {
      let xhr, formData;

      // \u8FD9\u662F\u5B98\u65B9\u4F8B\u5B50\uFF0C\u672C\u8D28\u662F\u901A\u8FC7blobInfo \u62FF\u5230file\u5BF9\u8C61\uFF0C\u901A\u8FC7FormData \u4F20\u7ED9\u540E\u7AEF\uFF0C\u7136\u540E\u7528success\u5C06\u7ED3\u679C\u8FD4\u56DE\u7ED9\u7F16\u8F91\u5668
      xhr = new XMLHttpRequest();
      xhr.withCredentials = false;
      xhr.open('POST', '/api/url');

      xhr.upload.onprogress = function (e) {
        progress((e.loaded / e.total) * 100);
      };

      xhr.onload = function () {
        let json;

        if (xhr.status === 403) {
          reject('HTTP Error: ' + xhr.status);
          return;
        }

        if (xhr.status < 200 || xhr.status >= 300) {
          reject('HTTP Error: ' + xhr.status);
          return;
        }

        json = JSON.parse(xhr.responseText);

        if (!json || typeof json.location != 'string') {
          reject('Invalid JSON: ' + xhr.responseText);
          return;
        }

        resolve(json.location);
      };

      xhr.onerror = function () {
        reject('Image upload failed due to a XHR Transport error. Code: ' + xhr.status);
      };

      formData = new FormData();
      formData.append('file', blobInfo.blob(), blobInfo.filename());

      xhr.send(formData);
    });
  };

  return (
    <RichTextEditor
      onEditorChange={onChange}
      init={{
        toolbar: defaultToolbar,
        images_upload_handler: imagesUploadHandler,
      }}
    />
  );
}
